{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Ondansetron has high absolute oral bioavailability (~85%) in humans, but it lacks the ionizable benzamidine and free carboxylic acid that create the query's zwitterionic, low-permeability character; this high-F result does not transfer to the query's absorption-limited structure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C36"],
      "claim": "Telmisartan, the closest analogue with a benzimidazole and carboxylic acid, has 43% absolute oral bioavailability, above the 20% threshold; however, it lacks the strongly basic benzamidine present in the query, so its moderate F does not overcome the query's additional permeability liability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C38"],
      "claim": "Indomethacin showed 13% oral bioavailability in preterm infants, a sub-20% human record; although this is population-specific and not mechanistically transferable to the query, it is the only affirmative sub-20% value in the evidence set and weakly supports the low-F direction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a zwitterionic benzimidazole bearing both a free benzamidine and a carboxylic acid, a combination that severely limits membrane permeability and oral absorption (dabigatran-like). The high-F analogues lack this amidine/carboxylate zwitterion; the closest analogue, telmisartan, has only the carboxylate and benzimidazole and is still above 20%. The only sub-20% record is condition-specific. Thus low F (<20%) is the better-supported prediction.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query or a close benzamidine/carboxylate zwitterion analogue.",
    "The only sub-20% human record (indomethacin in preterm infants) is confounded by developmental physiology and does not address the query's permeability barrier.",
    "All high-transfer analogues lack the strongly basic benzamidine, so their high-F results are not mechanistically transferable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

